"""Real browser coverage for the seven additional browser-ESM components."""
import asyncio,json,sys
from pathlib import Path
from playwright.async_api import async_playwright
async def main():
 base=sys.argv[1] if len(sys.argv)>1 else 'http://127.0.0.1:8845'
 out=Path(__file__).resolve().parents[1]/'artifacts';checks=[]
 async with async_playwright() as pw:
  browser=await pw.chromium.launch();context=await browser.new_context(viewport={'width':1440,'height':1100},permissions=['clipboard-read','clipboard-write']);page=await context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
  await page.goto(base,wait_until='networkidle')
  async def select(name):await page.locator('nav').get_by_role('button',name=name).click()
  slider=page.get_by_role('slider',name='Reveal dark');await slider.focus();await page.keyboard.press('End');assert await slider.input_value()=='100';await page.keyboard.press('Home');assert await slider.input_value()=='0';await page.keyboard.press('ArrowRight');assert await slider.input_value()=='1';await slider.fill('50')
  assert await page.locator('.cv-compare-frame img').evaluate_all('(imgs)=>imgs.every(x=>x.complete&&x.naturalWidth>0)')
  checks.append('Comparison: loaded actual images, native range Home/End/arrow updates')
  await page.screenshot(path=str(out/'clearvue-expanded-desktop.png'),full_page=True)
  await select('Command menu');launcher=page.get_by_role('button',name='Find an action');await launcher.click();search=page.get_by_role('searchbox',name='Search actions');await search.wait_for();await page.wait_for_timeout(100);assert await search.evaluate('(x)=>x===document.activeElement')
  await search.fill('nothingmatches');assert await page.get_by_text('No actions found. Try another word.').is_visible();await search.fill('review');await search.press('ArrowDown');assert await page.get_by_role('button',name='Review the brief').evaluate('(x)=>x===document.activeElement');await page.keyboard.press('End');assert await page.get_by_role('button',name='Run keyboard review').evaluate('(x)=>x===document.activeElement');await page.keyboard.press('Enter');assert not await page.get_by_role('dialog').is_visible();assert await launcher.evaluate('(x)=>x===document.activeElement')
  await launcher.click();await search.fill('');assert await page.get_by_role('button',name='Publish to production').is_disabled();await page.screenshot(path=str(out/'clearvue-command.png'));await page.keyboard.press('Escape');assert await launcher.evaluate('(x)=>x===document.activeElement');checks.append('Command menu: search/empty/disabled, focus, arrows, selection, Escape restoration')
  await select('Tag input');tag=page.get_by_role('textbox',name='Project focus',exact=True);await tag.fill('vue 3');await tag.press('Enter');assert await page.get_by_text('That tag is already included.').is_visible();await tag.fill('<img src=x onerror=alert(1)>');await tag.press('Enter');assert await page.locator('.cv-tags img').count()==0
  for value in ['Design','Testing','Extra']:await tag.fill(value);await tag.press('Enter')
  assert await page.get_by_text('Limit reached. Remove a tag before adding another.').is_visible();await page.get_by_role('button',name='Remove Vue 3',exact=True).click();assert await tag.evaluate('(x)=>x===document.activeElement');checks.append('Tags: controlled updates, duplicate/limit feedback, escaped text, removal focus')
  await select('Inline edit');edit=page.get_by_role('button',name='Edit Project name');await edit.click();field=page.get_by_role('textbox',name='Project name',exact=True);await field.fill('discard me');await field.press('Escape');assert await page.get_by_text('Saved value: A clearer handoff').is_visible();assert await edit.evaluate('(x)=>x===document.activeElement');await edit.click();await field.fill('');await field.press('Enter');assert await field.get_attribute('aria-invalid')=='true';await field.fill('Ready for review');await field.press('Enter');assert await page.get_by_text('Saved value: Ready for review').is_visible();checks.append('Inline edit: draft cancellation, empty validation, model commit, focus return')
  await select('Stepper');await page.get_by_role('button',name='Continue',exact=True).click();assert await page.get_by_text('Give your brief a name before continuing.').is_visible();await page.get_by_role('textbox',name='Brief name').fill('Keyboard audit');await page.get_by_role('button',name='Continue',exact=True).click();assert await page.get_by_role('heading',name='Review scope',exact=True).evaluate('(x)=>x===document.activeElement');await page.get_by_role('button',name='Back',exact=True).click();assert await page.get_by_role('textbox',name='Brief name').input_value()=='Keyboard audit';await page.get_by_role('button',name='Continue',exact=True).click();await page.get_by_role('button',name='Continue',exact=True).click();await page.get_by_role('button',name='Finish',exact=True).click();assert await page.get_by_text('Saved in this page session only. Nothing was sent.').is_visible();await page.get_by_role('button',name='Start again').click();checks.append('Stepper: validation gate, heading focus, retained draft, back, finish and restart')
  await select('File picker');file=page.get_by_label('Project brief',exact=True);await file.set_input_files({'name':'unsafe.exe','mimeType':'application/octet-stream','buffer':b'a'});assert await file.get_attribute('aria-invalid')=='true';await file.set_input_files({'name':'big.pdf','mimeType':'application/pdf','buffer':b'a'*2000001});assert await page.get_by_text('This file exceeds the size limit.').is_visible();await file.set_input_files({'name':'brief.txt','mimeType':'text/plain','buffer':b'Just a test'});assert await page.get_by_text('brief.txt · 1 KB selected').is_visible();await page.get_by_role('button',name='Remove file').click();assert await file.evaluate('(x)=>x===document.activeElement');checks.append('File picker: type and size rejection, valid selection, removal and focus')
  await select('Copy field');await page.get_by_role('button',name='Copy',exact=True).click();await page.get_by_text('Copied to clipboard.').wait_for();assert await page.evaluate('navigator.clipboard.readText()')=='https://github.com/neha-pd/clearvue';await page.evaluate("Object.defineProperty(navigator,'clipboard',{value:{writeText:()=>Promise.reject(new Error('denied'))},configurable:true})");await page.get_by_role('button',name='Copy',exact=True).click();await page.get_by_text('Clipboard unavailable. Select and copy the value manually.').wait_for();assert await page.get_by_role('textbox',name='ClearVue source').evaluate('(x)=>x===document.activeElement && x.selectionEnd===x.value.length');checks.append('Copy field: actual clipboard readback, denied fallback and selected text')
  await select('Comparison');await page.get_by_role('button',name='Dark mode',exact=True).click();await page.screenshot(path=str(out/'clearvue-expanded-dark.png'),full_page=True);await page.get_by_role('button',name='Light mode',exact=True).click();await page.set_viewport_size({'width':390,'height':844})
  for component in ['Comparison','Command menu','Stepper','Tag input','Inline edit','File picker','Copy field']:
   await select(component);assert await page.evaluate('document.documentElement.scrollWidth<=innerWidth'),component
  await select('Comparison');await page.screenshot(path=str(out/'clearvue-expanded-mobile.png'),full_page=True)
  await select('Command menu');await launcher.click();await page.screenshot(path=str(out/'clearvue-command-mobile.png'));assert await page.evaluate('document.documentElement.scrollWidth<=innerWidth');await page.keyboard.press('Escape');checks.append('All seven additions: mobile overflow and dark/light captures')
  assert not errors,errors
  (out/'extended-checks.json').write_text(json.dumps({'base_url':base,'checks':checks,'runtime_errors':errors},indent=2));print(json.dumps({'passed':len(checks),'checks':checks},indent=2));await browser.close()
asyncio.run(main())
